export type PeepId = keyof typeof PEEPS
export const peepSymbolId = (id: PeepId) => `peep-${id}`

/** 발 자리 (그림 폭에 대한 비율, 그림 맨 아래). 서 있는 사람을 이 점으로 땅에 세운다 (openpeeps PNG 에서 잰 값) */
export const FOOT_X: Record<PeepId, number> = {
  walkA: 0.5,
  walkB: 0.5,
  walkC: 0.48,
  walkD: 0.48,
  sitA: 0.41,
  sitB: 0.41,
  pointA: 0.4,
  standA: 0.55,
  standB: 0.5,
  standC: 0.52,
  standD: 0.49,
}

/** 앉은 그림에서 엉덩이 자리 (원본 좌표, 앉은 자세 365×576 기준) */
export const SIT_HIP = { x: 150, y: 372 } as const

/** 벤치 앉는 판 높이 (Greenery.Bench 의 z0 0.13 + 판 0.05) */
export const SEAT_Z = 0.18

/** 벤치에 앉은 사람의 엉덩이 자리 (격자). 3D 지도도 같은 자리에 앉힌다 */
export const seatOf = (x: number, y: number, dir: 'x' | 'y'): [number, number, number] => (dir === 'x' ? [x + 0.36, y + 0.13, SEAT_Z] : [x + 0.13, y + 0.36, SEAT_Z])

/** 사람 크기: 원본 713 높이 → 지도 37 (건물 벽 높이 1~1.5칸 옆에서 장난감처럼 보이지 않게) */
export const PEEP_K = 37 / 713

/** 한 문서에 한 번만 넣는 <symbol> 묶음. 검정 면에 같은 색 선(14)을 둘러 굵게 한다 (작게 그려도 선이 사라지지 않게) */
export const PEEP_DEFS = (Object.keys(PEEPS) as PeepId[])
  .map((id) => `<symbol id="${peepSymbolId(id)}" viewBox="0 0 ${PEEPS[id].w} ${PEEPS[id].h}">${PEEPS[id].art}</symbol>`)
  .join('')
